38	)
39	
40	func newAttachCmd() *cobra.Command {
41		var (
42			force     bool
43			agentFlag string
44		)
45		cmd := &cobra.Command{
46			Use:   "attach <session-id>",
47			Short: "Attach an existing agent session",
48			Long: `Attach an existing agent session that wasn't captured by hooks.
49	
50	This creates a checkpoint from the session's transcript and links it to the
51	last commit. Use this when hooks failed to fire or weren't installed when
52	the session started, or to attach a research session.
53	
54	If the last commit already has a checkpoint, the session is added to it.
55	Otherwise a new checkpoint is created.
56	
57	Works with any registered agent, including external agents enabled via
58	external_agents in settings. Run 'entire configure' to see the full list.`,
59			RunE: func(cmd *cobra.Command, args []string) error {
60				if len(args) != 1 {
61					return cmd.Help()
62				}
63				if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
64					return nil
65				}
66				// Discover external agents so --agent <external-name> is recognized
67				// and so auto-detection can find transcripts from external agents.
68				external.DiscoverAndRegister(cmd.Context())
69				agentName := types.AgentName(agentFlag)
70				return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], agentName, force)
71			},
72		}
73		cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
74		cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (see 'entire configure' for registered agents, including external)")
75		return cmd
76	}
77	
78	func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
79		// Initialize structured logger so logging.Warn/Info write to .entire/logs/ not stderr.
80		if err := logging.Init(ctx, sessionID); err != nil {
81			// Init failed — logging will use stderr fallback, non-fatal.
82			_ = err
83		}
84		defer logging.Close()
85	
86		logCtx := logging.WithComponent(ctx, "attach")
87	
88		// Open repository once — shared across all operations.
89		repo, err := openRepository(ctx)
90		if err != nil {
91			return err
92		}
93	
94		existingState, err := validateAttachPreconditions(ctx, repo, sessionID)
95		if err != nil {
96			return err
97		}
98	
99		headCommit, err := getHeadCommit(repo)
100		if err != nil {
101			return err
102		}
103	
104		// If session already has a checkpoint, just offer to link it.
105		if existingState != nil && !existingState.LastCheckpointID.IsEmpty() {
106			cpID := existingState.LastCheckpointID.String()
107			fmt.Fprintf(w, "Session %s already has checkpoint %s\n", sessionID, cpID)
108			if err := promptAmendCommit(logCtx, w, headCommit, cpID, force); err != nil {
109				logging.Warn(logCtx, "failed to amend commit", "error", err)
110				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpID)
111			}
112			return nil
113		}
114	
115		// Resolve agent and transcript path.
116		ag, transcriptPath, err := resolveAgentAndTranscript(logCtx, w, sessionID, agentName, existingState)
117		if err != nil {
118			return err
119		}
120	
121		transcriptData, err := ag.ReadTranscript(transcriptPath)
122		if err != nil {
123			return fmt.Errorf("failed to read transcript: %w", err)
124		}
125	
126		// Normalize Gemini transcripts for storage.
127		storedTranscript := transcriptData
128		if ag.Type() == agent.AgentTypeGemini {
129			if normalized, normErr := geminicli.NormalizeTranscript(transcriptData); normErr == nil {
130				storedTranscript = normalized
131			} else {
132				logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
133			}
134		}
135	
136		meta := extractTranscriptMetadata(transcriptData)
137	
138		// Determine checkpoint ID: reuse from HEAD if one exists, otherwise generate new.
139		checkpointID, isExistingCheckpoint := resolveCheckpointID(headCommit)
140	
141		// If HEAD references an existing checkpoint, make sure we have it locally
142		// before writing — otherwise we'd create a fresh session 0 under the same
143		// ID and overwrite the original on push.
144		repo, err = ensureCheckpointAvailable(ctx, logCtx, repo, checkpointID, isExistingCheckpoint)
145		if err != nil {
146			return err
147		}
148	
149		// Write directly to entire/checkpoints/v1.
150		store := cpkg.NewGitStore(repo)
151	
152		author, err := GetGitAuthor(ctx)
153		if err != nil {
154			return fmt.Errorf("failed to get git author: %w", err)
155		}
156	
157		var prompts []string
158		if meta.FirstPrompt != "" {
159			prompts = []string{meta.FirstPrompt}
160		}
161	
162		tokenUsage := agent.CalculateTokenUsage(logCtx, ag, transcriptData, 0, "")
163	
164		_, redactSpan := perf.Start(ctx, "redact_transcript")
165		redactedTranscript, redactErr := redact.JSONLBytes(storedTranscript)
166		redactSpan.End()
167		if redactErr != nil {
168			return fmt.Errorf("failed to redact transcript: %w", redactErr)
169		}
170	
171		writeOpts := cpkg.WriteCommittedOptions{
172			CheckpointID: checkpointID,
173			SessionID:    sessionID,
174			Strategy:     strategy.StrategyNameManualCommit,
175			Transcript:   redactedTranscript,
176			Prompts:      prompts,
177			AuthorName:   author.Name,
178			AuthorEmail:  author.Email,
179			Agent:        ag.Type(),
180			Model:        meta.Model,
181			TokenUsage:   tokenUsage,
182		}
183	
184		if compacted := compactTranscriptForStartLine(logCtx, redactedTranscript.Bytes(), cpkg.CommittedMetadata{
185			CheckpointID: checkpointID,
186			Agent:        ag.Type(),
187		}, 0); compacted != nil {
188			writeOpts.CompactTranscript = compacted
189		}
190	
191		v2 := settings.CheckpointsVersion(logCtx) == 2
192		if !v2 {
193			if err := store.WriteCommitted(ctx, writeOpts); err != nil {
194				return fmt.Errorf("failed to write checkpoint: %w", err)
195			}
196		}
197		// IsCheckpointsV2Enabled is true whenever v2 writes are enabled, including
198		// both v2-only mode (checkpoints_version == 2) and dual-write mode. Only
199		// v2-only mode propagates the error.
200		if settings.IsCheckpointsV2Enabled(logCtx) {
201			if err := writeAttachCheckpointV2(logCtx, repo, writeOpts); err != nil {
202				if v2 {
203					return fmt.Errorf("failed to write checkpoint to v2: %w", err)
204				}
205				logging.Warn(logCtx, "attach v2 dual-write failed", "error", err)
206			}
207		}
208	
209		// Create or update session state.
210		if err := saveAttachSessionState(logCtx, existingState, sessionID, ag.Type(), transcriptPath, checkpointID, meta, tokenUsage); err != nil {
211			logging.Warn(logCtx, "failed to save session state", "error", err)
212		}
213	
214		fmt.Fprintf(w, "Attached session %s\n", sessionID)
215		if isExistingCheckpoint {
216			fmt.Fprintf(w, "  Added to existing checkpoint %s\n", checkpointID)
217			return nil
218		}
219	
220		fmt.Fprintf(w, "  Created checkpoint %s\n", checkpointID)
221		cpIDStr := checkpointID.String()
222		if err := promptAmendCommit(logCtx, w, headCommit, cpIDStr, force); err != nil {
223			logging.Warn(logCtx, "failed to amend commit", "error", err)
224			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpIDStr)
225		}
226	
227		return nil
228	}
229	
230	// writeAttachCheckpointV2 writes attach-created checkpoints into the v2 refs.
231	func writeAttachCheckpointV2(ctx context.Context, repo *git.Repository, opts cpkg.WriteCommittedOptions) error {
232		v2URL, err := remote.FetchURL(ctx)
233		if err != nil {
234			logging.Debug(ctx, "attach: using origin for v2 store fetch remote",
235				slog.String("error", err.Error()),
236			)
237		}
238		v2Store := cpkg.NewV2GitStore(repo, v2URL)
239		if err := v2Store.WriteCommitted(ctx, opts); err != nil {
240			return fmt.Errorf("v2 write committed: %w", err)
241		}
242		return nil
243	}
244	
245	// getHeadCommit returns the HEAD commit object.
246	func getHeadCommit(repo *git.Repository) (*object.Commit, error) {
247		headRef, err := repo.Head()
248		if err != nil {
249			return nil, fmt.Errorf("failed to get HEAD: %w", err)
250		}
251		commit, err := repo.CommitObject(headRef.Hash())
252		if err != nil {
253			return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
254		}
255		return commit, nil
256	}
257	
258	// ensureCheckpointAvailable makes sure the checkpoint referenced by HEAD is
259	// present locally before the attach writes to it. Without this guard, attach
260	// would create a fresh session 0 under the same ID and overwrite the original
261	// session data on push.
262	//
263	// Only the local branch counts — remote-tracking presence is not enough.
264	// If only the remote-tracking ref exists, a subsequent WriteCommitted creates
265	// a brand-new orphan local branch with an empty tree, which would clobber
266	// the remote on push.
267	//
268	// Fast path: check local refs directly — no network. If missing, trigger the
269	// metadata fetch fallback chain used by `entire resume` (which advances the
270	// local ref on success) and re-check. Returns a possibly-freshly-opened repo
271	// handle so go-git sees any newly fetched packfiles.
272	func ensureCheckpointAvailable(ctx, logCtx context.Context, repo *git.Repository, checkpointID id.CheckpointID, isExistingCheckpoint bool) (*git.Repository, error) {
273		if !isExistingCheckpoint {
274			return repo, nil
275		}
276	
277		v2Only := settings.CheckpointsVersion(logCtx) == 2
278	
279		present, readErr := checkpointPresentLocally(ctx, repo, checkpointID, v2Only)
280		if readErr != nil {
281			return repo, fmt.Errorf("failed to read checkpoint %s: %w", checkpointID, readErr)
282		}
283		if present {
284			return repo, nil
285		}
286	
287		// Missing locally — try to refresh, then re-check. Use the same fetch
288		// chain `entire resume` uses for the active storage version (v2 refs live
289		// under refs/entire/, not refs/heads/, so v1 and v2 need different
290		// refspecs).
291		freshRepo, fetchErr := refreshCheckpointRefs(ctx, v2Only)
292		if fetchErr != nil {
293			logging.Warn(logCtx, "failed to refresh metadata branch before attach; proceeding with local state",
294				slog.String("error", fetchErr.Error()))
295		} else {
296			repo = freshRepo
297			present, readErr = checkpointPresentLocally(ctx, repo, checkpointID, v2Only)
298			if readErr != nil {
299				return repo, fmt.Errorf("failed to read checkpoint %s after refresh: %w", checkpointID, readErr)
300			}
301			if present {
302				return repo, nil
303			}
304		}
305	
306		branchDescription := "entire/checkpoints/v1 branch"
307		if v2Only {
308			branchDescription = "v2 /main ref"
309		}
310		return repo, fmt.Errorf(
311			"checkpoint %s referenced by HEAD is missing from the local %s after a refresh attempt. Creating a fresh checkpoint here would overwrite the original session data on push. Run:\n\n    %s\n\nthen re-run attach. If the colleague who made this commit hasn't pushed their checkpoint metadata yet, ask them to do so first",
312			checkpointID.String(), branchDescription, suggestCheckpointFetchCommand(logCtx, v2Only),
313		)
314	}
315	
316	// refreshCheckpointRefs runs the resume-equivalent fetch chain for the storage
317	// version we're about to write to. Returns a freshly-opened repo so go-git
318	// sees any newly-fetched packfiles and ref updates.
319	func refreshCheckpointRefs(ctx context.Context, v2Only bool) (*git.Repository, error) {
320		if v2Only {
321			_, repo, err := getV2MetadataTree(ctx)
322			return repo, err
323		}
324		_, repo, err := getMetadataTree(ctx)
325		return repo, err
326	}
327	
328	// checkpointPresentLocally reports whether the checkpoint already exists on
329	// the local ref we would write to. For v1 / dual-write, that's the local
330	// entire/checkpoints/v1 branch (remote-tracking alone is not enough — see
331	// ensureCheckpointAvailable). For v2-only mode, it's the v2 /main ref, which
332	// has no remote-tracking analog and is therefore already local-only by
333	// construction.
334	func checkpointPresentLocally(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, v2Only bool) (bool, error) {
335		if v2Only {
336			v2URL, urlErr := remote.FetchURL(ctx)
337			if urlErr != nil {
338				logging.Debug(ctx, "attach: using origin for v2 store fetch remote",
339					slog.String("error", urlErr.Error()),
340				)
341			}
342			summary, err := cpkg.NewV2GitStore(repo, v2URL).ReadCommitted(ctx, checkpointID)
343			if err != nil {
344				return false, err //nolint:wrapcheck // Caller wraps with checkpoint ID context
345			}
346			return summary != nil, nil
347		}
348	
349		localRef := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
350		if _, err := repo.Reference(localRef, true); err != nil {
351			// Local branch ref doesn't exist — treat as "not present locally".
352			// We deliberately do not fall back to remote-tracking: see
353			// ensureCheckpointAvailable's docstring.
354			return false, nil //nolint:nilerr // Missing ref is the "absent" signal, not an error.
355		}
356		summary, err := cpkg.NewGitStore(repo).ReadCommitted(ctx, checkpointID)
357		if err != nil {
358			return false, err //nolint:wrapcheck // Caller wraps with checkpoint ID context
359		}
360		return summary != nil, nil
361	}
362	
363	// suggestCheckpointFetchCommand returns a git fetch command the user can
364	// paste to pull the missing metadata ref. v2 refs live under refs/entire/
365	// (not refs/heads/), so they need an explicit fully-qualified refspec;
366	// v1 lives on a regular branch and its short name is enough.
367	func suggestCheckpointFetchCommand(ctx context.Context, v2Only bool) string {
368		ref := "entire/checkpoints/v1:entire/checkpoints/v1"
369		if v2Only {
370			ref = paths.V2MainRefName + ":" + paths.V2MainRefName
371		}
372		if remote.Configured(ctx) {
373			if url, err := remote.FetchURL(ctx); err == nil && url != "" {
374				return fmt.Sprintf("git fetch %s %s", url, ref)
375			}
376		}
377		return "git fetch origin " + ref
378	}
379	
380	// resolveCheckpointID returns the checkpoint ID to use for the attach.
381	// If HEAD already has an Entire-Checkpoint trailer, reuses that ID (the session
382	// gets added as an additional session in the existing checkpoint).
383	// Otherwise generates a new ID.
384	func resolveCheckpointID(headCommit *object.Commit) (id.CheckpointID, bool) {
385		existing := trailers.ParseAllCheckpoints(headCommit.Message)
386		if len(existing) > 0 {
387			return existing[len(existing)-1], true
388		}
389	
390		cpID, err := id.Generate()
391		if err != nil {
392			// Generation only fails if crypto/rand fails — extremely unlikely.
393			// Fall back to empty which will cause WriteCommitted to fail with a clear error.
394			return id.EmptyCheckpointID, false
395		}
396		return cpID, false
397	}
398	
399	// saveAttachSessionState creates or updates the session state file for the attached session.
400	// If existingState is non-nil, it is updated in place (avoids a redundant disk load).
401	func saveAttachSessionState(ctx context.Context, existingState *session.State, sessionID string, agentType types.AgentType, transcriptPath string, checkpointID id.CheckpointID, meta transcriptMetadata, tokenUsage *agent.TokenUsage) error {
402		stateStore, err := session.NewStateStore(ctx)
403		if err != nil {
404			return fmt.Errorf("failed to open session store: %w", err)
405		}
406	
407		now := time.Now()
408		state := existingState
409		if state == nil {
410			state = &session.State{
411				SessionID: sessionID,
412				StartedAt: now,
413			}
414		}
415	
416		state.CLIVersion = versioninfo.Version
417		state.AttachedManually = true
418		state.AgentType = agentType
419		state.TranscriptPath = transcriptPath
420		state.LastCheckpointID = checkpointID
421		state.Phase = session.PhaseEnded
422		state.LastInteractionTime = &now
423		if meta.TurnCount > 0 {
424			state.SessionTurnCount = meta.TurnCount
425		}
426		if meta.Model != "" {
427			state.ModelName = meta.Model
428		}
429		if meta.FirstPrompt != "" {
430			state.LastPrompt = meta.FirstPrompt
431		}
432		if tokenUsage != nil {
433			state.TokenUsage = tokenUsage
434		}
435	
436		if err := stateStore.Save(ctx, state); err != nil {
437			return fmt.Errorf("failed to save session state: %w", err)
438		}
439		return nil
440	}
441	
442	// validateAttachPreconditions checks session ID format and git repo state.
443	// Returns the existing session state if the session is already tracked (nil if new).
444	func validateAttachPreconditions(ctx context.Context, repo *git.Repository, sessionID string) (*session.State, error) {
445		if err := validation.ValidateSessionID(sessionID); err != nil {
446			return nil, fmt.Errorf("invalid session ID: %w", err)
447		}
448	
449		if strategy.IsEmptyRepository(repo) {
450			return nil, errors.New("repository has no commits yet — make an initial commit before running attach")
451		}
452	
453		store, err := session.NewStateStore(ctx)
454		if err != nil {
455			return nil, fmt.Errorf("failed to open session store: %w", err)
456		}
457		existing, err := store.Load(ctx, sessionID)
458		if err != nil {
459			return nil, fmt.Errorf("failed to check existing session: %w", err)
460		}
461	
462		return existing, nil
463	}
464	
465	// resolveAgentAndTranscript resolves the agent and transcript path.
466	// For existing sessions, resolves the agent from session state's AgentType.
467	// For new sessions, uses the --agent flag with auto-detection fallback.
468	func resolveAgentAndTranscript(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, existingState *session.State) (agent.Agent, string, error) {
469		ag, err := resolveAgent(existingState, agentName)
470		if err != nil {
471			return nil, "", err
472		}
473	
474		transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, ag)
475		if err != nil {
476			// Auto-detect: try all other agents.
477			detectedAg, detectedPath, detectErr := detectAgentByTranscript(ctx, sessionID, agentName)
478			if detectErr != nil {
479				return nil, "", fmt.Errorf("%w (also tried auto-detecting other agents: %w)", err, detectErr)
480			}
481			ag = detectedAg
482			transcriptPath = detectedPath
483			logging.Info(ctx, "auto-detected agent from transcript", "agent", ag.Name())
484			fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
485		}
486	
487		return ag, transcriptPath, nil
488	}
489	
490	// resolveAgent resolves the agent to use. For existing sessions with an AgentType,
491	// uses agent.GetByAgentType. Otherwise falls back to the --agent flag.
492	func resolveAgent(existingState *session.State, agentName types.AgentName) (agent.Agent, error) {
493		if existingState != nil && existingState.AgentType != "" {
494			ag, err := agent.GetByAgentType(existingState.AgentType)
495			if err == nil {
496				return ag, nil
497			}
498			// Fall through to flag-based resolution.
499		}
500		ag, err := agent.Get(agentName)
501		if err != nil {
502			return nil, fmt.Errorf("agent %q not available: %w", agentName, err)
503		}
504		return ag, nil
505	}
506	
507	// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
508	// project directories if needed.
509	func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
510		transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
511		if err != nil {
512			return "", fmt.Errorf("failed to resolve transcript path: %w", err)
513		}
514		// Only call PrepareTranscript when the file already exists — it flushes
515		// in-progress writes, but can't conjure a file that was never started.
516		// This avoids agents like Cursor polling for 3s on non-existent files
517		// during auto-detection.
518		if _, statErr := os.Stat(transcriptPath); statErr == nil {
519			if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
520				if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
521					logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
522				}
523			}
524			return transcriptPath, nil
525		}
526		found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
527		if searchErr == nil {
528			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
529			return found, nil
530		}
531		logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
532		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
533	}
534	
535	// detectAgentByTranscript tries all registered agents (except skip) to find one whose
536	// transcript resolution succeeds for the given session ID.
537	func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
538		for _, name := range agent.List() {
539			if name == skip {
540				continue
541			}
542			ag, err := agent.Get(name)
543			if err != nil {
544				continue
545			}
546			path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
547			if resolveErr != nil {
548				logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
549				continue
550			}
551			return ag, path, nil
552		}
553		return nil, "", errors.New("transcript not found for any registered agent")
554	}
555	
556	// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
557	// When force is true, it amends without prompting.
558	func promptAmendCommit(ctx context.Context, w io.Writer, headCommit *object.Commit, checkpointIDStr string, force bool) error {
559		shortHash := headCommit.Hash.String()[:7]
560		subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
561	
562		// Skip amending if this exact checkpoint ID is already in the commit.
563		for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
564			if existing.String() == checkpointIDStr {
565				fmt.Fprintf(w, "Commit %s already has Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
566				return nil
567			}
568		}
569	
570		fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
571	
572		amend := true
573		if !force {
574			if !interactive.CanPromptInteractively() {
575				// Non-interactive: can't prompt, print trailer for manual use.
576				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
577				return nil
578			}
579			form := NewAccessibleForm(
580				huh.NewGroup(
581					huh.NewConfirm().
582						Title("Amend the last commit in this branch?").
583						Affirmative("Y").
584						Negative("n").
585						Value(&amend),
586				),
587			)
588			if err := form.Run(); err != nil {
589				return fmt.Errorf("prompt failed: %w", err)
590			}
591		}
592	
593		if !amend {
594			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
595			return nil
596		}
597	
598		newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
599	
600		cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
601		if output, err := cmd.CombinedOutput(); err != nil {
602			return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
603		}
604	
605		fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
606		return nil
607	}
608

